// Statement assets, embedded.
//
// These were fetched from the app's own domain at runtime, which failed in a
// way worth remembering: the files had not been deployed yet, Vercel's SPA
// rewrite answered with index.html, and fontkit reported "Unknown font format"
// — an HTML page dressed as a font. Embedding removes the network call, the
// deploy-order coupling, and that whole class of failure.
//
// Regenerate with scripts/build-statement-assets.py after changing a font.

const B64: Record<string, string> = {
  regular: '',
  semibold: '',
  mono: '',
  monoBold: '',
  logo: '',
}

function bytes(b64: string): Uint8Array {
  const bin = atob(b64)
  const u8 = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i)
  return u8
}

let cache: Record<string, Uint8Array> | null = null
export function statementAssets(): Record<string, Uint8Array> {
  if (cache) return cache
  cache = Object.fromEntries(Object.entries(B64).map(([k, v]) => [k, bytes(v)]))
  // A TTF starts with 0x00010000 or "true"/"OTTO". If an asset is ever swapped
  // for something else, say so here rather than deep inside fontkit.
  for (const k of ['regular', 'semibold', 'mono', 'monoBold']) {
    const b = cache[k]
    const ok = (b[0] === 0x00 && b[1] === 0x01) || (b[0] === 0x74 && b[1] === 0x72) || (b[0] === 0x4f && b[1] === 0x54)
    if (!ok) throw new Error(`statement asset "${k}" is not a TTF/OTF`)
  }
  return cache
}